    int i;
    struct posix_acl *posix_acl;

    if (aclp->acl_cnt > XFS_ACL_MAX_ENTRIES)
        return ERR_PTR(-EINVAL);

    posix_acl = kmalloc(sizeof(*posix_acl) + (aclp->acl_cnt - 1) * sizeof(struct posix_acl_entry),
                        GFP_KERNEL);
    if (!posix_acl)
        return ERR_PTR(-ENOMEM);

    posix_acl->a_count = aclp->acl_cnt;

    for (i = 0; i < aclp->acl_cnt; i++) {
        struct xfs_acl_entry *entry = &aclp->acl_entry[i];
        struct posix_acl_entry *posix_entry = &posix_acl->a_entries[i];
        int tag;
        int id;

        switch (entry->e_tag) {
        case XFS_ACL_TAG_USER_OBJ:
            tag = ACL_USER_OBJ;
            id = -1;
            break;
        case XFS_ACL_TAG_GROUP_OBJ:
            tag = ACL_GROUP_OBJ;
            id = -1;
            break;
        case XFS_ACL_TAG_USER:
            tag = ACL_USER;
            id = entry->e_id;
            break;
        case XFS_ACL_TAG_GROUP:
            tag = ACL_GROUP;
            id = entry->e_id;
            break;
        case XFS_ACL_TAG_OTHER:
