struct posix_acl *convert_xfs_acl_to_posix(struct xfs_acl *aclp) {
    int count = aclp->acl_count;
    struct posix_acl *posix_acl;
    struct posix_acl_entry *entry;
    int i;

    if (count < 0 || count > XFS_ACL_MAX_ENTRIES)
        return ERR_PTR(-EINVAL);

    posix_acl = kmalloc(sizeof(struct posix_acl) + count * sizeof(struct posix_acl_entry), GFP_KERNEL);
    if (!posix_acl)
        return ERR_PTR(-ENOMEM);

    posix_acl->a_count = count;
    entry = &posix_acl->a_entries[0];

    for (i = 0; i < count; i++) {
        struct xfs_acl_entry *xfs_entry = &aclp->acl_entry[i];
        struct posix_acl_entry *posix_entry = &entry[i];

        switch (xfs_entry->e_tag) {
            case XFS_ACL_USER_OBJ:
                posix_entry->e_tag = POSIX_ACL_USER_OBJ;
                break;
            case XFS_ACL_GROUP_OBJ:
                posix_entry->e_tag = POSIX_ACL_GROUP_OBJ;
                break;
            case XFS_ACL_OTHER:
                posix_entry->e_tag = POSIX_ACL_OTHER;
                break;
            case XFS_ACL_USER:
                posix_entry->e_tag = POSIX_ACL_USER;
                posix_entry->e_id = xfs_entry->e_id;
                break;
            case XFS_ACL_GROUP:
                posix_entry->e_tag = POSIX_ACL_GROUP;
                posix_entry->e_id = xfs_entry->e_id;
                break;
            default:
                kfree(posix_acl);
                return ERR_PTR(-EINVAL);
        }

        posix_entry->e_perms = xfs_entry->e_perms;
        posix_entry->e_tag = xfs_entry->e_tag;
    }

    return posix_acl;
}

#include <stdlib.h>
#include <errno.h>

struct posix_acl;

struct posix_acl *convert_xfs_acl_to_posix(struct xfs_acl *aclp) {
    unsigned int count = aclp->acl_count;
    struct posix_acl *acl;
    unsigned int i;

    if (count > XFS_ACL_MAX_ENTRIES)
        return ERR_PTR(-EINVAL);

    acl = kmalloc(sizeof(struct posix_acl) + count * sizeof(acl->acl[0]), GFP_KERNEL);
    if (!acl)
        return ERR_PTR(-ENOMEM);

    acl->a_count = count;
    for (i = 0; i < count; i++) {
        struct xfs_acl_entry *entry = &aclp->acl_entry[i];
        struct posix_acl_entry *pa = &acl->acl[i];

        switch (entry->tag) {
        case XFS_ACL_TAG_USER_OBJ:
            pa->e_tag = POSIX_ACL_USER_OBJ;
            pa->e_id = 0; /* default owner ID */
            break;
        case XFS_ACL_TAG_GROUP_OBJ:
            pa->e_tag = POSIX_ACL_GROUP_OBJ;
            pa->e_id = 0; /* default group ID */
            break;
        case XFS_ACL_TAG_OTHER:
            pa->e_tag = POSIX_ACL_OTHER;
            pa->e_id = 0;
            break;
        case XFS_ACL_TAG_USER:
            pa->e_tag = POSIX_ACL_USER;
            pa->e_id = entry->id;
            break;
        case XFS_ACL_TAG_GROUP:
            pa->e_tag = POSIX_ACL_GROUP;
            pa->e_id = entry->id;
            break;
        default:
            kfree(acl);
            return ERR_PTR(-EINVAL);
        }

        pa->e_perm = entry->perms;
    }

    return acl;
}

struct posix_acl *xfs_acl_from_disk(struct xfs_acl *aclp)
{
    int count = aclp->acl_count;
    struct posix_acl *posix_acl;
    struct posix_acl_entry *entry;
    int i;

    if (count < 0 || count > XFS_ACL_MAX_ENTRIES)
        return ERR_PTR(-EINVAL);

    posix_acl = kmalloc(sizeof(struct posix_acl) +
                        count * sizeof(struct posix_acl_entry),
                        GFP_KERNEL);
    if (!posix_acl)
        return ERR_PTR(-ENOMEM);

    posix_acl->a_count = count;

    for (i = 0; i < count; i++) {
        entry = &posix_acl->a_entries[i];
        entry->e_tag = aclp->acl_entry[i].ae_tag;
        entry->e_perm = aclp->acl_entry[i].ae_perm;

        if (entry->e_tag == ACL_USER || entry->e_tag == ACL_GROUP) {
            entry->e_id = aclp->acl_entry[i].ae_id;
        } else {
            entry->e_id = ACL_UNDEFINED_ID;
        }
    }

    return posix_acl;
}

struct posix_acl *xfs_acl_from_disk(struct xfs_acl *aclp) {
    struct posix_acl *acl;
    int i;
    int count = aclp->acl_count;

    if (count < 0 || count > XFS_ACL_MAX_ENTRIES)
        return ERR_PTR(-EINVAL);

    acl = posix_acl_alloc(count, GFP_KERNEL);
    if (!acl)
        return ERR_PTR(-ENOMEM);

    for (i = 0; i < count; i++) {
        struct xfs_acl_entry *entry = &aclp->acl_entry[i];
        struct posix_acl_entry *pa = &acl->a_entries[i];
        int tag;
        int perm;

        tag = le16_to_cpu(entry->e_tag);
        perm = le16_to_cpu(entry->e_perm);

        switch (tag) {
        case XFS_ACL_USER_OBJ:
        case XFS_ACL_GROUP_OBJ:
        case XFS_ACL_MASK:
        case XFS_ACL_OTHER:
            pa->e_tag = tag;
            pa->e_perm = perm;
            pa->e_uid = MAKE_UID_CURRENT();
            pa->e_gid = MAKE_GID_CURRENT();
            break;
        case XFS_ACL_USER:
        case XFS_ACL_GROUP:
            pa->e_tag = tag;
            pa->e_perm = perm;
            pa->e_uid = le32_to_cpu(entry->e_id);
            pa->e_gid = le32_to_cpu(entry->e_id);
            break;
        default:
            posix_acl_release(acl);
            return ERR_PTR(-EINVAL);
        }
    }

    return acl;
}
